/**
 * Jinx Pukka + Summoner: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Pukka
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L118). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import type { ReminderLabel } from '#lib/core/data/index.ts';
import { characterChanger, earlyOnly } from '#lib/core/rules/becomes.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Pukka + Summoner jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'pukka', 'summoner');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('pukka')?.name).toBe('Pukka');
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['pukka', 'summoner'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['pukka'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
	});

	const ids = ['summoner', 'pukka', 'imp', 'chef', 'empath', 'monk', 'saint'];
	const cast = ['summoner', 'chef', 'empath', 'monk', 'saint'];
	const base = scenario(cast, { script: scriptOf(ids) });
	const night = (s: typeof base, label: string) =>
		s.reminder('summoner', 'summoner', label as ReminderLabel);

	describe('the Summoner may summon a Pukka a night early', () => {
		it("is data in the Summoner's rules", () => {
			// Wiki: "The Summoner may summon a Pukka on the 2nd night instead of the 3rd."
			expect(ownJinxRules(base.game, 'summoner', 'pukka', base.characters)).toEqual({
				earlierToken: { token: 'Night 2' }
			});
		});

		it('lets the Summoner make only a Pukka on its 2nd night', () => {
			// Wiki: "The Summoner may summon a Pukka on the 2nd night instead of the 3rd."
			const s = night(base, 'Night 2');
			expect(characterChanger(s.game, 'summoner', s.characters)).toBe(s.seat('summoner'));
			expect(earlyOnly(s.game, 'summoner', s.characters)).toEqual(['pukka']);
		});

		it('keeps the usual choice of Demon on the 3rd night', () => {
			// Wiki: "instead of the 3rd."
			const s = night(base, 'Night 3');
			expect(characterChanger(s.game, 'summoner', s.characters)).toBe(s.seat('summoner'));
			expect(earlyOnly(s.game, 'summoner', s.characters)).toBe(undefined);
		});

		it('summons nothing on the 2nd night without the Pukka on the script', () => {
			// Wiki: "The Summoner may summon a Pukka on the 2nd night"
			const plain = night(
				scenario(cast, { script: scriptOf(ids.filter((id) => id !== 'pukka')) }),
				'Night 2'
			);
			expect(characterChanger(plain.game, 'summoner', plain.characters)).toBe(undefined);
		});
	});
});
